//! # `Res2Net` prefabs

// The prefabs and the stage table between the `gen_resnet_kin_prefabs`
// markers are generated by `tools/gen_resnet_kin_prefabs.py` from timm's own
// `res2net.py` entrypoints and models; edit the script, not them.

use alloc::{
    vec,
    vec::Vec,
};

use crate::{
    data::pretrained::{
        PrefabTable,
        Prefabs,
    },
    kits::images::classification::{
        res2net::Res2NetContractConfig,
        resnet::{
            BottleneckPolicyConfig,
            ResNetContractConfig,
            ResNetStemKind,
        },
    },
};

impl Res2NetContractConfig {
    /// A `Res2Net` of 1000 classes: `ResNet` bottleneck stages of `layers`
    /// units, `base_width` channels per chunk per 64 planes in `cardinality`
    /// groups, `scale` chunks.
    fn res2net(
        layers: Vec<usize>,
        base_width: usize,
        cardinality: usize,
        scale: usize,
    ) -> Self {
        Self::new(
            ResNetContractConfig::new(layers, 1000).with_bottleneck_policy(Some(
                BottleneckPolicyConfig::new()
                    .with_base_width(base_width)
                    .with_cardinality(cardinality),
            )),
        )
        .with_scale(scale)
    }

    /// This on timm's `deep` stem of `stem_width`, its shortcuts pooled
    /// (`avg_down`) as `avg_down` says.
    fn with_deep_stem(
        self,
        stem_width: usize,
        avg_down: bool,
    ) -> Self {
        Self {
            resnet: self
                .resnet
                .with_stem_type(ResNetStemKind::Deep)
                .with_stem_width(stem_width)
                .with_avg_down(avg_down),
            ..self
        }
    }

    // gen_resnet_kin_prefabs: begin fns
    /// The `res2net50_14w_8s` prefab: `Res2Net` `res2net50_14w_8s`; 8 chunks of
    /// 14 per 64 planes.
    pub fn res2net50_14w_8s() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 14, 1, 8)
    }

    /// The `res2net50_26w_4s` prefab: `Res2Net` `res2net50_26w_4s`; 4 chunks of
    /// 26 per 64 planes.
    pub fn res2net50_26w_4s() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 26, 1, 4)
    }

    /// The `res2net50_26w_6s` prefab: `Res2Net` `res2net50_26w_6s`; 6 chunks of
    /// 26 per 64 planes.
    pub fn res2net50_26w_6s() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 26, 1, 6)
    }

    /// The `res2net50_26w_8s` prefab: `Res2Net` `res2net50_26w_8s`; 8 chunks of
    /// 26 per 64 planes.
    pub fn res2net50_26w_8s() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 26, 1, 8)
    }

    /// The `res2net50_48w_2s` prefab: `Res2Net` `res2net50_48w_2s`; 2 chunks of
    /// 48 per 64 planes.
    pub fn res2net50_48w_2s() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 48, 1, 2)
    }

    /// The `res2net50d` prefab: `Res2Net` `res2net50d`; 4 chunks of 26 per 64
    /// planes, the `deep` stem of 32, average-pool shortcuts.
    pub fn res2net50d() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 26, 1, 4).with_deep_stem(32, true)
    }

    /// The `res2next50` prefab: `Res2Net` `res2next50`; 4 chunks of 4 per 64
    /// planes, 8 groups.
    pub fn res2next50() -> Self {
        Self::res2net(vec![3, 4, 6, 3], 4, 8, 4)
    }

    /// The `res2net101_26w_4s` prefab: `Res2Net` `res2net101_26w_4s`; 4 chunks
    /// of 26 per 64 planes.
    pub fn res2net101_26w_4s() -> Self {
        Self::res2net(vec![3, 4, 23, 3], 26, 1, 4)
    }

    /// The `res2net101d` prefab: `Res2Net` `res2net101d`; 4 chunks of 26 per 64
    /// planes, the `deep` stem of 32, average-pool shortcuts.
    pub fn res2net101d() -> Self {
        Self::res2net(vec![3, 4, 23, 3], 26, 1, 4).with_deep_stem(32, true)
    }
    // gen_resnet_kin_prefabs: end fns
}

/// The `Res2Net` geometries by name, timm's architecture names: a
/// [`Res2NetContractConfig`] of 1000 classes for every architecture of
/// timm's `res2net.py` with hub weights.
///
/// A prefab has no weights: a timm row takes the classes from its
/// `config.json`.
impl Prefabs for Res2NetContractConfig {
    const PREFABS: PrefabTable<Self> = &[
        // gen_resnet_kin_prefabs: begin table
        ("res2net50_14w_8s", Self::res2net50_14w_8s),
        ("res2net50_26w_4s", Self::res2net50_26w_4s),
        ("res2net50_26w_6s", Self::res2net50_26w_6s),
        ("res2net50_26w_8s", Self::res2net50_26w_8s),
        ("res2net50_48w_2s", Self::res2net50_48w_2s),
        ("res2net50d", Self::res2net50d),
        ("res2next50", Self::res2next50),
        ("res2net101_26w_4s", Self::res2net101_26w_4s),
        ("res2net101d", Self::res2net101d),
        // gen_resnet_kin_prefabs: end table
    ];
    const PREFAB_TABLE: &'static str = "res2net";
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        blocks::{
            conv::ConvBlock2dMeta,
            images::models::conv_net::ConvChainMeta,
        },
        burner::module::ToStructureConfig,
    };

    /// Each architecture as timm builds it: its stem's conv widths, and each
    /// stage's `(depth, width, mixer width)`, read from timm's modules (the
    /// mixer width is the first `1x1`'s output, `scale` chunks).
    #[allow(clippy::type_complexity)]
    const TIMM_STAGES: &[(&str, &[usize], [(usize, usize, usize); 4])] = &[
        // gen_resnet_kin_prefabs: begin stages
        (
            "res2net50_14w_8s",
            &[64],
            [(3, 256, 112), (4, 512, 224), (6, 1024, 448), (3, 2048, 896)],
        ),
        (
            "res2net50_26w_4s",
            &[64],
            [(3, 256, 104), (4, 512, 208), (6, 1024, 416), (3, 2048, 832)],
        ),
        (
            "res2net50_26w_6s",
            &[64],
            [
                (3, 256, 156),
                (4, 512, 312),
                (6, 1024, 624),
                (3, 2048, 1248),
            ],
        ),
        (
            "res2net50_26w_8s",
            &[64],
            [
                (3, 256, 208),
                (4, 512, 416),
                (6, 1024, 832),
                (3, 2048, 1664),
            ],
        ),
        (
            "res2net50_48w_2s",
            &[64],
            [(3, 256, 96), (4, 512, 192), (6, 1024, 384), (3, 2048, 768)],
        ),
        (
            "res2net50d",
            &[32, 32, 64],
            [(3, 256, 104), (4, 512, 208), (6, 1024, 416), (3, 2048, 832)],
        ),
        (
            "res2next50",
            &[64],
            [
                (3, 256, 128),
                (4, 512, 256),
                (6, 1024, 512),
                (3, 2048, 1024),
            ],
        ),
        (
            "res2net101_26w_4s",
            &[64],
            [
                (3, 256, 104),
                (4, 512, 208),
                (23, 1024, 416),
                (3, 2048, 832),
            ],
        ),
        (
            "res2net101d",
            &[32, 32, 64],
            [
                (3, 256, 104),
                (4, 512, 208),
                (23, 1024, 416),
                (3, 2048, 832),
            ],
        ),
        // gen_resnet_kin_prefabs: end stages
    ];

    /// Every prefab's stem and stages are timm's.
    #[test]
    fn test_prefab_stages_are_timms() {
        assert_eq!(
            TIMM_STAGES.len(),
            Res2NetContractConfig::prefab_names().len()
        );
        for (name, stem, stages) in TIMM_STAGES {
            let structure = Res2NetContractConfig::expect_prefab(name)
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let ours: Vec<_> = structure
                .stem
                .convs
                .iter()
                .map(|c| c.out_channels())
                .collect();
            assert_eq!(&ours, stem, "{name}: the stem");
            let ours: Vec<_> = structure
                .stages
                .iter()
                .map(|s| {
                    let unit = &s.units[0];
                    (
                        s.units.len(),
                        unit.out_channels(),
                        unit.convs[0].out_channels(),
                    )
                })
                .collect();
            assert_eq!(ours, stages, "{name}");
        }
    }
}
